action.code:
if (!head) return false;
if (head->val == value) {
    ListNode* temp = head;
    head = head->next;
    delete temp;
    return true;
}
ListNode* current = head;
while (current->next && current->next->val != value) {
    current = current->next;
}
if (current->next) {
    ListNode* temp = current->next;
    current->next = current->next->next;
    delete temp;
    return true;
}
return false;

